//! The Principal type is generated from the pinned contract's schema, so a field the contract adds
//! reaches the adapter mechanically. The generator knows the shapes the schema uses: strings (with
//! an enum, or as a date-time read as a `SystemTime`), booleans, arrays of strings, and objects.

use serde_json::Value;
use std::fmt::Write as _;
use std::path::Path;

const GENERATED: &str = "src/identity/principal.rs";

const HEADER: &str =
    "// Generated by tests/principal_type.rs from the Principal contract's schema; do not edit.
//! The Principal identity states on every channel, as the pinned contract's schema describes it.

use std::time::SystemTime;
";

fn pascal(name: &str) -> String {
    name.split(['-', '_'])
        .map(|part| {
            let mut chars = part.chars();
            chars
                .next()
                .map(|first| first.to_uppercase().chain(chars).collect::<String>())
                .unwrap_or_default()
        })
        .collect()
}

fn snake(name: &str) -> String {
    let mut out = String::new();
    for c in name.chars() {
        if c.is_uppercase() {
            out.push('_');
        }
        out.extend(c.to_lowercase());
    }
    out
}

/// description as `///` lines of at most 100 characters, each indented by indent.
fn doc(description: Option<&str>, indent: &str) -> String {
    let Some(description) = description else {
        return String::new();
    };
    let width = 100 - indent.len() - 4;
    let mut out = String::new();
    let mut line = String::new();
    for word in description.split_whitespace() {
        if !line.is_empty() && line.len() + 1 + word.len() > width {
            let _ = writeln!(out, "{indent}/// {line}");
            line.clear();
        }
        if !line.is_empty() {
            line.push(' ');
        }
        line.push_str(word);
    }
    let _ = writeln!(out, "{indent}/// {line}");
    out
}

fn enumeration(name: &str, field: &Value, values: &[Value]) -> String {
    let mut values: Vec<&str> = values.iter().filter_map(Value::as_str).collect();
    values.sort_unstable();
    let mut out = doc(field["description"].as_str(), "");
    out.push_str("#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]\n");
    let _ = writeln!(out, "pub enum {name} {{");
    for v in &values {
        let _ = writeln!(out, "    /// `{v}`\n    {},", pascal(v));
    }
    out.push_str("}\n\n");
    let _ = writeln!(out, "impl {name} {{");
    out.push_str("    /// The contract's name for this value.\n    #[must_use]\n");
    out.push_str("    pub fn as_str(self) -> &'static str {\n        match self {\n");
    for v in &values {
        let _ = writeln!(out, "            Self::{} => \"{v}\",", pascal(v));
    }
    out.push_str("        }\n    }\n\n");
    out.push_str("    /// The value the contract names `value`, if any.\n    #[must_use]\n");
    out.push_str(
        "    pub fn from_contract(value: &str) -> Option<Self> {\n        match value {\n",
    );
    for v in &values {
        let _ = writeln!(out, "            \"{v}\" => Some(Self::{}),", pascal(v));
    }
    out.push_str("            _ => None,\n        }\n    }\n}\n");
    out
}

fn type_of(name: &str, field: &Value, types: &mut Vec<String>) -> Result<String, String> {
    if let Some(values) = field["enum"].as_array() {
        types.push(enumeration(&pascal(name), field, values));
        return Ok(pascal(name));
    }
    match (field["type"].as_str(), field["format"].as_str()) {
        (Some("string"), Some("date-time")) => Ok("SystemTime".into()),
        (Some("string"), _) => Ok("String".into()),
        (Some("boolean"), _) => Ok("bool".into()),
        (Some("array"), _) if field["items"]["type"] == "string" => Ok("Vec<String>".into()),
        (Some("object"), _) => {
            let object = structure(&pascal(name), field, types)?;
            types.push(object);
            Ok(pascal(name))
        }
        (kind, _) => Err(format!("no Rust type for {name} (type {kind:?})")),
    }
}

fn structure(name: &str, schema: &Value, types: &mut Vec<String>) -> Result<String, String> {
    let required: Vec<&str> = schema["required"]
        .as_array()
        .map(|r| r.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let mut out = doc(schema["description"].as_str(), "");
    out.push_str("#[derive(Clone, Debug, PartialEq, Eq)]\n");
    let _ = writeln!(out, "pub struct {name} {{");
    for (field, spec) in schema["properties"].as_object().into_iter().flatten() {
        let rust = type_of(field, spec, types)?;
        let rust = if required.contains(&field.as_str()) {
            rust
        } else {
            format!("Option<{rust}>")
        };
        let fallback = format!("The contract's `{field}`.");
        out.push_str(&doc(
            Some(spec["description"].as_str().unwrap_or(&fallback)),
            "    ",
        ));
        let _ = writeln!(out, "    pub {}: {rust},", snake(field));
    }
    out.push_str("}\n");
    Ok(out)
}

/// The Rust source of the Principal type, from the contract's schema.
fn generate(schema: &Value) -> Result<String, String> {
    let mut types = Vec::new();
    let principal = structure(
        schema["title"].as_str().unwrap_or("Principal"),
        schema,
        &mut types,
    )?;
    types.push(principal);
    Ok(format!("{HEADER}\n{}", types.join("\n")))
}

#[test]
fn the_principal_type_is_what_the_pinned_schema_generates() {
    // PRINCIPAL_UPDATE=true task test
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let schema = std::fs::read_to_string(root.join("contract/principal.schema.json")).unwrap();
    let want = generate(&serde_json::from_str(&schema).unwrap()).unwrap();
    if std::env::var("PRINCIPAL_UPDATE").as_deref() == Ok("true") {
        std::fs::write(root.join(GENERATED), &want).unwrap();
    }

    assert_eq!(std::fs::read_to_string(root.join(GENERATED)).unwrap(), want);
}

#[test]
fn the_principal_type_is_not_generated_for_a_shape_the_generator_does_not_know() {
    let schema = serde_json::json!({"title": "T", "type": "object", "properties": {"n": {"type": "number"}}});

    assert_eq!(
        generate(&schema),
        Err("no Rust type for n (type Some(\"number\"))".into())
    );
}

#[test]
fn every_kind_and_via_is_named_as_the_contract_names_it() {
    use jorisjonkers_commons::identity::{Kind, Via};
    let kinds = [Kind::User, Kind::Machine].map(|k| Kind::from_contract(k.as_str()) == Some(k));
    let vias = [Via::Session, Via::PersonalToken, Via::Tool, Via::Machine]
        .map(|v| Via::from_contract(v.as_str()) == Some(v));

    assert_eq!(
        (kinds, vias, Via::PersonalToken.as_str()),
        ([true; 2], [true; 4], "personal-token")
    );
}
